"""
Real geographic boundaries of Ukraine's 27 first-level regions.

Coordinates are pre-projected (equirectangular, latitude-corrected) into a
flat SVG viewBox and simplified (Douglas-Peucker) for compact, fast-rendering
mobile geometry. Source: amCharts open geodata (oblast-level polygons),
re-derived at build time -- this module only stores the final numbers, no
network access is required at runtime.

Two views of the same geometry are exposed:
  * ``REGION_RINGS`` -- raw ``(x, y)`` point rings, used for point-in-polygon
    hit-testing when the user taps the map.
  * ``REGION_PATHS`` -- the same rings pre-formatted as SVG path ``d``
    strings, used for drawing.
"""

from __future__ import annotations

import math
from typing import Optional

from app.data.oblast_districts import DISTRICT_RINGS
from app.geo_utils import repair_self_intersecting_ring
from app.models.alert_models import Region

#: Logical SVG canvas size that all coordinates below are expressed in.
VIEWBOX_WIDTH: float = 762.0
VIEWBOX_HEIGHT: float = 511.0

# --- Projection constants -----------------------------------------------
# These are the EXACT values used to pre-project the region polygons below
# (equirectangular projection, latitude-corrected, then padded). They are
# kept here (not just baked into the numbers) so any *new* point -- e.g. a
# city marker for the "Рух загроз" map -- can be projected into the same
# coordinate space with ``project_lat_lon`` and align pixel-perfectly with
# the region borders, instead of re-deriving a slightly different formula.
_MIN_LON = 22.1398
_MAX_LON = 40.2185
_MIN_LAT = 44.3881
_MAX_LAT = 52.3758
_MEAN_LAT_RAD = math.radians((_MIN_LAT + _MAX_LAT) / 2)
_COS_LAT = math.cos(_MEAN_LAT_RAD)
_RAW_VIEWBOX_WIDTH = 750.0  # VIEWBOX_WIDTH minus 2x padding below
_SCALE = _RAW_VIEWBOX_WIDTH / ((_MAX_LON - _MIN_LON) * _COS_LAT)
_PADDING = 6.0


def project_lat_lon(lat: float, lon: float) -> tuple[float, float]:
    """Project a (lat, lon) pair into this module's SVG viewBox space.

    Uses the identical formula and constants used to generate
    ``REGION_RINGS``/``REGION_PATHS`` below, so the result can be safely
    mixed with that geometry (e.g. to place a city marker on the map).
    """
    x = (lon - _MIN_LON) * _COS_LAT * _SCALE + _PADDING
    y = (_MAX_LAT - lat) * _SCALE + _PADDING
    return round(x, 2), round(y, 2)


def unproject_to_lat_lon(point: tuple[float, float]) -> tuple[float, float]:
    """Exact inverse of ``project_lat_lon`` -- viewBox (x, y) back to (lat, lon).

    The forward projection is a simple affine transform (no re-derivation
    needed): this just runs the same formula backwards, using the same
    constants, so round-tripping a point through both functions returns
    the original coordinates (up to the 2-decimal rounding already done
    by ``project_lat_lon``).
    """
    x, y = point
    lon = (x - _PADDING) / (_COS_LAT * _SCALE) + _MIN_LON
    lat = _MAX_LAT - (y - _PADDING) / _SCALE
    return lat, lon


_EARTH_RADIUS_KM = 6371.0088  # IUGG mean Earth radius


def bearing_and_distance_km(
    origin: tuple[float, float], target: tuple[float, float]
) -> tuple[float, float]:
    """Real great-circle initial bearing (0=N, clockwise) + distance (km)
    from ``origin`` to ``target``, both given as ``(lat, lon)`` in degrees.

    Standard haversine distance + forward-azimuth formulas -- used by the
    Threat Compass page to plot a real target at its actual measured
    bearing/distance from a reference point, never an estimated/guessed
    one.
    """
    lat1, lon1 = math.radians(origin[0]), math.radians(origin[1])
    lat2, lon2 = math.radians(target[0]), math.radians(target[1])
    d_lat = lat2 - lat1
    d_lon = lon2 - lon1

    a = math.sin(d_lat / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin(d_lon / 2) ** 2
    distance_km = 2 * _EARTH_RADIUS_KM * math.asin(min(1.0, math.sqrt(a)))

    y = math.sin(d_lon) * math.cos(lat2)
    x = math.cos(lat1) * math.sin(lat2) - math.sin(lat1) * math.cos(lat2) * math.cos(d_lon)
    bearing_degrees = (math.degrees(math.atan2(y, x)) + 360.0) % 360.0

    return bearing_degrees, distance_km


