#: Final, repaired region boundary data -- everything else in this
#: module and the rest of the app uses this, never ``_RAW_REGION_RINGS``.
#: The self-intersection repair itself lives in ``app.geo_utils`` so the
#: exact same logic also applies to ``DISTRICT_RINGS`` -- one
#: implementation instead of two that could drift apart.
REGION_RINGS: dict[Region, list[list[tuple[float, float]]]] = {
    region: [repair_self_intersecting_ring(ring) for ring in rings]
    for region, rings in _RAW_REGION_RINGS.items()
}


def _rings_to_path(rings: list[list[tuple[float, float]]]) -> str:
    """Turn one region's point rings into a single SVG path ``d`` string."""
    parts: list[str] = []
    for ring in rings:
        head = ring[0]
        tail = " ".join(f"L {x} {y}" for x, y in ring[1:])
        parts.append(f"M {head[0]} {head[1]} {tail} Z")
    return " ".join(parts)


#: Ready-to-draw SVG path data for each region, derived from ``REGION_RINGS``.
REGION_PATHS: dict[Region, str] = {
    region: _rings_to_path(rings) for region, rings in REGION_RINGS.items()
}


def _point_in_ring(point: tuple[float, float], ring: list[tuple[float, float]]) -> bool:
    """Standard ray-casting point-in-polygon test against one closed ring."""
    x, y = point
    inside = False
    x1, y1 = ring[-1]
    for x2, y2 in ring:
        if (y1 > y) != (y2 > y):
            x_intersect = x1 + (y - y1) * (x2 - x1) / (y2 - y1)
            if x < x_intersect:
                inside = not inside
        x1, y1 = x2, y2
    return inside


def _point_to_ring_boundary_distance(point: tuple[float, float], ring: list[tuple[float, float]]) -> float:
    """Minimum distance from ``point`` to any edge of ``ring``.

    Used only to disambiguate ``region_at_point`` when a point matches
    more than one region's polygon (see that function's docstring) --
    not used for anything else, so it has no effect on hit-testing for
    the (overwhelmingly common) case of exactly one match.
    """
    px, py = point
    best = float("inf")
    x1, y1 = ring[-1]
    for x2, y2 in ring:
        dx, dy = x2 - x1, y2 - y1
        if dx == 0.0 and dy == 0.0:
            dist = math.hypot(px - x1, py - y1)
        else:
            t = max(0.0, min(1.0, ((px - x1) * dx + (py - y1) * dy) / (dx * dx + dy * dy)))
            proj_x, proj_y = x1 + t * dx, y1 + t * dy
            dist = math.hypot(px - proj_x, py - proj_y)
        if dist < best:
            best = dist
        x1, y1 = x2, y2
    return best


def region_at_point(point: tuple[float, float]) -> "Region | None":
    """Return the region whose polygon contains ``point`` (viewBox units), if any.

    Shared by the map's own tap hit-testing (``UkraineMap``) and by the
    "Рух загроз" region filter, which needs to know which oblast a
    city's projected point falls into -- same geometry, same test, one
    implementation instead of two copies drifting apart.

    A hand-digitized administrative border is never perfectly precise,
    so two neighboring oblasts' polygons can slightly overlap right
    along their shared edge -- verified this actually happens for a
    small fraction of points near Chernihiv's borders with Kyiv
    Oblast/Poltava/Sumy, for example. When a point matches more than
    one region this way, the true containing region is picked by which
    one the point sits farthest inside of (see
    ``_point_to_ring_boundary_distance``): the correct region contains
    it well within its own shape, while an overlapping neighbor only
    reaches it in a thin sliver right at that neighbor's own edge.
    """
    matches: list[tuple[Region, float]] = []
    for region, rings in REGION_RINGS.items():
        for ring in rings:
            if _point_in_ring(point, ring):
                matches.append((region, _point_to_ring_boundary_distance(point, ring)))
                break  # a region's own rings never overlap each other; one match is enough

    if not matches:
        return None
    if len(matches) == 1:
        return matches[0][0]
    return max(matches, key=lambda item: item[1])[0]
    return None


def district_at_point(region: "Region", point: tuple[float, float]) -> Optional[str]:
    """Return the raion ("district") name whose polygon contains
    ``point`` (viewBox units) within ``region``, if any.

    Same ray-casting test as ``region_at_point``, one level down --
    reuses ``app.data.oblast_districts.DISTRICT_RINGS`` (already the
    geometry drawn for the focused-oblast district overlay) rather than
    a second copy of it, for the interactive-districts tap feature.
    Returns ``None`` for a region with no district data (Kyiv City,
    Sevastopol -- see that module's docstring) or a point outside every
    district (shouldn't happen for a point already known to be inside
    the region, but simplification can leave tiny gaps at a border).
    """
    districts = DISTRICT_RINGS.get(region)
    if not districts:
        return None
    for name, rings in districts.items():
        for ring in rings:
            if _point_in_ring(point, ring):
                return name
    return None


def regions_bounding_box(regions: "set[Region] | list[Region]") -> tuple[float, float, float, float]:
    """Return (min_x, min_y, max_x, max_y) in viewBox units spanning ``regions``.

    Used by the "Рух загроз" map to crop/zoom to a set of selected
    oblasts instead of always rendering the whole country. Raises
    ``ValueError`` for an empty input -- callers should treat "no
    selection" as "show everything" *before* calling this, not by
    passing an empty set here.
    """
    if not regions:
        raise ValueError("regions_bounding_box() requires at least one region")

    xs: list[float] = []
    ys: list[float] = []
    for region in regions:
        for ring in REGION_RINGS[region]:
            for x, y in ring:
                xs.append(x)
                ys.append(y)
    return min(xs), min(ys), max(xs), max(ys)

